ALTER TABLE category ALTER COLUMN name TYPE varchar(60);
ALTER TABLE category ADD COLUMN code varchar(80);
UPDATE category SET code='category-' || id;
UPDATE category SET name=CASE name WHEN 'Koncert' THEN 'Музика' WHEN 'Sport' THEN 'Спорт' WHEN 'Sztuka' THEN 'Мистецтво' ELSE name END;
INSERT INTO category(name,code) SELECT label,code FROM (VALUES ('Освіта','education'),('Волонтерство','volunteering'),('Зустрічі','meetups'),('Фестивалі','festivals'),('Для дітей','children'),('Інше','other')) AS defaults(label,code) WHERE NOT EXISTS(SELECT 1 FROM category c WHERE lower(c.name)=lower(defaults.label));
ALTER TABLE category ALTER COLUMN code SET NOT NULL;
CREATE UNIQUE INDEX category_code_uk ON category(code);
CREATE TABLE tag(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(30) NOT NULL, normalized_name varchar(60) NOT NULL UNIQUE);
CREATE TABLE event_tag(event_id bigint NOT NULL REFERENCES event(id) ON DELETE CASCADE, tag_id bigint NOT NULL REFERENCES tag(id), PRIMARY KEY(event_id,tag_id));
CREATE INDEX event_tag_tag_idx ON event_tag(tag_id,event_id);
CREATE TABLE category_request(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(60) NOT NULL, normalized_name varchar(100) NOT NULL, user_id bigint NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, status varchar(16) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')), reason varchar(500), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX category_request_pending_uk ON category_request(normalized_name) WHERE status='PENDING';
